#!/usr/bin/env python3
"""Writes THIRD_PARTY_NOTICES (the root file and its copy in every crate that
ships a LICENSE): the notices of the projects pikapro is derived from, and
the licenses of the Rust crates compiled into the Python package's extension
module.

    python3 .github/scripts/third_party_notices.py           # (re)write them
    python3 .github/scripts/third_party_notices.py --check   # exit 1 if stale

Run it after changing the Showdown pin or pikapro-py's dependencies (a
`Cargo.lock` change under pyo3 or numpy). It needs:

- cargo-about (`cargo install cargo-about --locked --features cli`), which
  reads each crate's license files from the local cargo registry;
- the oracle's node_modules (`cd tools/showdown-oracle && npm ci`), for
  Showdown's LICENSE at the pinned commit.

Only crates linked into the extension are listed: the wheels' platforms,
normal dependencies, no build scripts' dependencies and no proc-macros
(those run at build time and ship nothing). A dual-licensed crate
(`MIT OR Apache-2.0`) is redistributed under MIT; the Apache-2.0 text
follows for reference.
"""

from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "THIRD_PARTY_NOTICES"
SHOWDOWN_LICENSE = ROOT / "tools/showdown-oracle/node_modules/pokemon-showdown/LICENSE"

#: The wheels' targets (.github/workflows/wheels.yml).
TARGETS = [
    "x86_64-unknown-linux-gnu",
    "aarch64-unknown-linux-gnu",
    "x86_64-unknown-linux-musl",
    "aarch64-unknown-linux-musl",
    "x86_64-apple-darwin",
    "aarch64-apple-darwin",
    "x86_64-pc-windows-msvc",
]
FEATURES = "python,pyo3/abi3-py310"

#: poke-env's LICENSE, as shipped in poke_env-0.16.1.dist-info/licenses.
POKE_ENV_LICENSE = """\
MIT License

Copyright (c) 2019 hsahovic

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is
furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all
copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.
"""

HEADER = """\
Third-party notices for pikapro

pikapro itself is MIT licensed (see LICENSE). It is derived from the
projects in sections 1 and 2, and the Python package's compiled extension
module contains the Rust crates in section 3. Their licenses require the
notices below to accompany copies of the software.

pikapro is not affiliated with or endorsed by Pokémon Showdown, Nintendo,
Creatures Inc., Game Freak or The Pokémon Company. Pokémon and all related
names are trademarks of Nintendo, Creatures Inc., Game Freak and The
Pokémon Company.
"""

SHOWDOWN_INTRO = """\
Pokémon Showdown
https://github.com/smogon/pokemon-showdown

The battle engine (the crate `pikapro`) is a port of Showdown's simulator
(`sim/`), and the team validator (`pikapro-validate`), the battle stream
(`pikapro-server`) and the text protocol (`pikapro-protocol`) port the
corresponding parts of Showdown. The game data (`pikapro-data`, and the
sets in `pikapro-teams`) is generated from Showdown's data files. Every
crate and program built on them, the Python package included, contains
this work.
"""

POKE_ENV_INTRO = """\
poke-env
https://github.com/hsahovic/poke-env

The baseline players of `pikapro-rl` (`src/baselines/`, and so the
Python package's built-in opponents) are a port of poke-env 0.16.1's
`player/baselines.py`. The Python package's `pikapro.compat.poke_env`
works with poke-env, which is installed separately and not bundled.
"""

CRATES_INTRO = """\
Rust crates in the Python package's extension module

The wheels (and a wheel built from the sdist) statically link these crates
into `pikapro/_pikapro`. The crates on crates.io don't depend on them.
Generated by .github/scripts/third_party_notices.py with cargo-about.
"""

RULE = "=" * 78


def run(*args: str) -> str:
    p = subprocess.run(args, cwd=ROOT, capture_output=True, text=True)
    if p.returncode != 0:
        raise SystemExit(f"{' '.join(args)} failed:\n{p.stderr}")
    return p.stdout


def linked_crates() -> set[tuple[str, str]]:
    """(name, version) of each non-workspace crate linked into the module."""
    linked = set()
    for target in TARGETS:
        out = run(
            "cargo", "tree", "-p", "pikapro-py", "--features", FEATURES, "--locked",
            "-e", "normal,no-proc-macro", "--target", target, "--prefix", "none",
            "-f", "{p}",
        )
        for line in out.splitlines():
            name, version = line.split()[:2]
            if "(" not in line:  # a workspace crate prints its path
                linked.add((name, version.lstrip("v")))
    return linked


def about() -> dict:
    config = "\n".join([
        # Unicode-3.0: unicode-ident, under the proc-macros (not linked).
        'accepted = ["MIT", "BSD-2-Clause", "Apache-2.0", "Unicode-3.0"]',
        "ignore-build-dependencies = true",
        "ignore-dev-dependencies = true",
        f"targets = {json.dumps(TARGETS)}",
    ])
    with tempfile.TemporaryDirectory() as tmp:
        cfg = Path(tmp) / "about.toml"
        cfg.write_text(config + "\n")
        out = Path(tmp) / "about.json"
        run(
            "cargo", "about", "generate", "--format", "json", "--offline", "--locked",
            "-c", str(cfg), "-m", "crates/pikapro-py/Cargo.toml",
            "--features", FEATURES.replace(",", " "), "-o", str(out),
        )
        return json.loads(out.read_text())


def apache_text(data: dict) -> str:
    """The Apache-2.0 text, from a dual-licensed crate's LICENSE-APACHE."""
    for crate in data["crates"]:
        path = Path(crate["package"]["manifest_path"]).with_name("LICENSE-APACHE")
        if crate["package"]["name"] == "ndarray" and path.exists():
            return path.read_text()
    raise SystemExit("no LICENSE-APACHE found (ndarray's)")


def render() -> str:
    if not SHOWDOWN_LICENSE.exists():
        raise SystemExit(f"{SHOWDOWN_LICENSE} is missing: run `npm ci` in tools/showdown-oracle")
    data = about()
    linked = linked_crates()
    packages = {
        (c["package"]["name"], c["package"]["version"]): c["package"] for c in data["crates"]
    }
    missing = linked - set(packages)
    if missing:
        raise SystemExit(f"cargo-about didn't report {sorted(missing)}")

    parts = [HEADER, RULE, "1. " + SHOWDOWN_INTRO, SHOWDOWN_LICENSE.read_text().rstrip() + "\n",
             RULE, "2. " + POKE_ENV_INTRO, POKE_ENV_LICENSE, RULE, "3. " + CRATES_INTRO]

    rows = []
    for name, version in sorted(linked):
        p = packages[(name, version)]
        rows.append(f"  {name} {version} ({p['license']}) {p.get('repository') or ''}".rstrip())
    rows.append(
        "  the Rust standard library (MIT OR Apache-2.0; The Rust Project Developers,\n"
        "  under the same MIT text as libc below) https://github.com/rust-lang/rust"
    )
    parts.append("\n".join(rows) + "\n")

    # Each distinct license text once, with the crates it covers.
    for lic in data["licenses"]:
        users = sorted({
            f"{u['crate']['name']} {u['crate']['version']}"
            for u in lic["used_by"]
            if (u["crate"]["name"], u["crate"]["version"]) in linked
        })
        if not users:
            continue
        text = lic["text"].strip("\n")
        head = f"{lic['id']}, for: {', '.join(users)}"
        if not re.search(r"^\s*copyright", text, re.I | re.M):
            authors = sorted({
                a.split(" <")[0]
                for u in lic["used_by"]
                if (u["crate"]["name"], u["crate"]["version"]) in linked
                for a in packages[(u["crate"]["name"], u["crate"]["version"])]["authors"]
            })
            who = ", ".join(authors) if authors else "their authors"
            head += f"\n(the license file names no copyright holder: {who})"
        parts.append("-" * 78 + "\n" + head + "\n\n" + text + "\n")
    parts.append(
        "-" * 78 + "\nApache-2.0, the alternative license of the dual-licensed crates above\n"
        "and of the Rust standard library, for reference\n\n" + apache_text(data).strip("\n") + "\n"
    )
    return "\n".join(parts)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="exit 1 if a file is stale")
    args = parser.parse_args()
    text = render()
    copies = [OUT] + sorted(
        d / "THIRD_PARTY_NOTICES" for d in (ROOT / "crates").iterdir() if (d / "LICENSE").exists()
    )
    stale = [p for p in copies if not p.exists() or p.read_text() != text]
    if args.check:
        for p in stale:
            print(f"{p.relative_to(ROOT)} is stale: run {Path(__file__).relative_to(ROOT)}")
        return 1 if stale else 0
    for p in stale:
        p.write_text(text)
        print(f"wrote {p.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
